  /**
   * <!-- begin-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Fills all newly reachable tiles up to the given water distance from the source.
   * Algorithm:
   * 1. If distance is less than or equal to prevFilledDistance, do nothing.
   * 2. Starting from the source cell, perform breadth-first expansion through connected cells.
   * 3. Water may move from one pipe to an adjacent pipe only when the current pipe connection
   *    direction matches the opposite direction of the neighboring pipe.
   * 4. Mark newly reachable fillable cells and termination cells as filled.
   * 5. Record newly filled coordinates in filledTiles.
   * 6. Update prevFilledDistance and prevFilledTiles to reflect the latest expansion state.
   * Related Features:
   * - filledTiles: records coordinates of newly filled tiles
   * - prevFilledDistance: prevents repeated work for the same distance
   * - prevFilledTiles: tracks how many tiles were filled previously
   * - sourceCell: flow origin
   * - sinkCell: possible termination target
   * - cell: grid used to inspect neighboring cells
   * Related Classes: Map, Coordinate, FillableCell, TerminationCell, Pipe, Direction
   * Input:
   * - distance: non-negative water expansion distance from the source.
   * Output:
   * - None.
   * Pre-condition:
   * - The map is initialized.
   * - The source cell exists.
   * - distance is non-negative.
   * Post-condition:
   * - All cells reachable within distance through valid pipe connectivity are marked filled.
   * - Newly filled coordinates are stored in filledTiles.
   * - The internal previous-distance and previous-filled-count tracking is updated.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance <= prevFilledDistance)
    {
      return;
    }
    int before = getFilledTiles().size();
    if (getSourceCell() != null)
    {
      getSourceCell().setFilled(true);
    }
    if (cell != null && getSourceCell() != null)
    {
      ArrayDeque<edu.pa19.Cell> queue = new ArrayDeque<edu.pa19.Cell>();
      Set<edu.pa19.Cell> visited = new HashSet<edu.pa19.Cell>();
      queue.add(getSourceCell());
      visited.add(getSourceCell());

      while (!queue.isEmpty())
      {
        edu.pa19.Cell current = queue.remove();
        Coordinate coord = current.getCoord();
        int r = coord.getRow();
        int c = coord.getCol();

        for (Direction dir : Direction.values())
        {
          int nr = r;
          int nc = c;
          switch (dir)
          {
            case UP: nr = r - 1; break;
            case DOWN: nr = r + 1; break;
            case LEFT: nc = c - 1; break;
            case RIGHT: nc = c + 1; break;
          }

          if (nr < 0 || nc < 0 || nr >= cell.length || nc >= cell[nr].length)
          {
            continue;
          }

          edu.pa19.Cell next = cell[nr][nc];
          if (visited.contains(next))
          {
            continue;
          }

          boolean reachable = false;
          if (current instanceof FillableCell && next instanceof FillableCell)
          {
            Pipe cp = ((FillableCell) current).getPipe();
            Pipe np = ((FillableCell) next).getPipe();
            if (cp != null && np != null && cp.getConnections().contains(dir) && np.getConnections().contains(opposite(dir)))
            {
              reachable = true;
            }
          }
          else if (current instanceof FillableCell && next instanceof TerminationCell)
          {
            Pipe cp = ((FillableCell) current).getPipe();
            reachable = cp != null && cp.getConnections().contains(dir);
          }
          else if (current instanceof FillableCell && next instanceof FillableCell)
          {
            Pipe cp = ((FillableCell) current).getPipe();
            reachable = cp != null && cp.getConnections().contains(dir);
          }
          else if (current instanceof TerminationCell && next instanceof FillableCell)
          {
            Pipe np = ((FillableCell) next).getPipe();
            reachable = np != null && np.getConnections().contains(opposite(dir));
          }

          if (reachable)
          {
            visited.add(next);
            queue.add(next);
            if (next instanceof FillableCell)
            {
              FillableCell fc = (FillableCell) next;
              if (!fc.getPipe().isFilled())
              {
                fc.getPipe().setFilled(true);
                getFilledTiles().add(fc.getCoord());
              }
            }
            else if (next instanceof TerminationCell)
            {
              TerminationCell tc = (TerminationCell) next;
              if (!tc.isFilled())
              {
                tc.setFilled(true);
                getFilledTiles().add(tc.getCoord());
              }
            }
          }
        }
      }
    }
    prevFilledDistance = distance;
    prevFilledTiles = before;
  }

